-- 목적: book_text 페이지 단위 본문 적재 (asb · 이 파일: 8of11)
-- 실행자: 팀장(Supabase SQL Editor). 워커 초안. 워커 DB 직접 쓰기 금지.
-- 근거 ADR: ADR-0056 (ADR-0056 D1·D2·D4·D5) · Accepted 2026-08-10
-- source 라벨: manifest_txt_v1
-- 이 파일 담당: 48권 / 454행 (정제 후 빈 면 1행 포함 — D7)
-- 생성기: scripts/tts_pilot/gen_book_text_sql_v2.py
-- 매핑: page_index = (P번호|json page) - 1 (0-based, D2/D11). blocks = NULL(원천에 블록 정보 없음).
-- 정제: tts_targets.sanitize() 공유(D6). 표지 행 없음(D3).
-- 인용: $$ 달러 인용. 생성 시 '$$' 포함·'$' 종결 전수 가드 통과.
-- 중복: ON CONFLICT (book_id, page_index) DO NOTHING — 기존 행을 덮어쓰지 않는다.
--
-- ★ 이 파일은 ROLLBACK; 으로 끝난다. [적재검증]까지 기대값과 일치하면
--   마지막 ROLLBACK; 을 COMMIT; 으로 직접 바꿔 타이핑해 확정한다.

-- ───────── [선검증] 트랜잭션 밖 ─────────
-- (a) 대상 권의 기존 book_text 행 수 — 기대 0. 0이 아니면 중단하고 보고할 것.
SELECT count(*) AS rows_before FROM book_text bt
  JOIN books b ON b.id = bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('35433', '35467', '35476', '35491', '35553', '35554', '35574', '35582', '35588', '35593', '35594', '35613', '35623', '35626', '35631', '35643', '35645', '35646', '35647', '35666', '35669', '35732', '35744', '35866', '35934', '36026', '36028', '36030', '36034', '36036', '36038', '36089', '36106', '36128', '36221', '36489', '36503', '36558', '36586', '36647', '36705', '36714', '36739', '36774', '36775', '36825', '36832', '36842');
-- (b) 대상 source_id 중 books에 존재하는 권 수 — 기대 48
SELECT count(*) AS books_found FROM books
  WHERE source_platform='african_storybook' AND source_id IN ('35433', '35467', '35476', '35491', '35553', '35554', '35574', '35582', '35588', '35593', '35594', '35613', '35623', '35626', '35631', '35643', '35645', '35646', '35647', '35666', '35669', '35732', '35744', '35866', '35934', '36026', '36028', '36030', '36034', '36036', '36038', '36089', '36106', '36128', '36221', '36489', '36503', '36558', '36586', '36647', '36705', '36714', '36739', '36774', '36775', '36825', '36832', '36842');

-- ───────── [적재] ─────────
BEGIN;
INSERT INTO book_text (book_id, page_index, text, blocks, source)
SELECT b.id, v.page_index, v.text, NULL::jsonb, $$manifest_txt_v1$$
  FROM (VALUES
    ('35433', 0, $$I am a duck. I hatched from an egg.$$),
    ('35433', 1, $$I spend a lot of time around water.$$),
    ('35433', 2, $$I dabble in the ponds. I love getting wet.$$),
    ('35433', 3, $$I waddle with my webbed feet.$$),
    ('35433', 4, $$I wiggle with my tail.$$),
    ('35433', 5, $$My mouth is called a bill. I quack and drink with it.$$),
    ('35433', 6, $$I play in the grass. I play around in ponds.$$),
    ('35433', 7, $$Do you think I sleep in a nest?$$),
    ('35467', 0, $$It's such a beautiful day right!!@We would like to narrate you all a story about an adorable girl MEERA!$$),
    ('35467', 1, $$Meera is a 7 year old girl like us. She is a simple, generous and thoughtful girl who lives with her Amma Ms. Naina and her Achi Rajnikanth and her lovely friends@Jack, Jayashree and Jessica in a small village !$$),
    ('35467', 2, $$Meera loves to draw, play football, swim in the backwaters, make jewellery with coconut leaves and many such fun things. @Apart from all these things, she enjoys celebrating everything around her!!$$),
    ('35467', 3, $$It's her birthday tomorrow and she is super excited about it. She has been planning from a very long time to celebrate her birthday in the best way possible.$$),
    ('35467', 4, $$It's her birthday today and all her friends :@Jack,Jaya shree and Jessica came to her early in the morning to celebrate her day.... They were very happy to celebrate Meera's birthday the way she wanted!!!$$),
    ('35467', 5, $$Meera sold the jewellery which she made with the coconut leaves, @to celebrate her birthday. With that money she and her friends bought everything which is necessary for her celebration. They split up in to groups and got started.$$),
    ('35467', 6, $$Ms. Naina, Jack and Jayashree teamed up to bake a chocolate cake and cook. Mr. Rajnikanth and Jessica teamed up to decorate the whole garden bright and colourful!$$),
    ('35467', 7, $$Meera is so happy already seeing everyone on tasks, sharing, caring and enjoying what they are doing for her. Everyone had a great time baking the cake, getting the lights done and putting up the balloons!!$$),
    ('35467', 8, $$They are all set and her guests have arrived right on time..@Her guests are the children of her age who have not so great things in their life. The poor and needy children of her place.@Jayashree started singing a song and everyone$$),
    ('35467', 9, $$Danced to her song wishing and greeting Meera a very happy birthday, the needy kids feasted their tummies with yummy food Meera and her friends have prepared for them, sang happily, danced joyfully and enjoyed to fullest..$$),
    ('35467', 10, $$Meera was super happy seeing them happy and bid them bye with a a planter, Saying..take care of this plant and it will take care of you!@She said, @What you give is what you get back. @Nurture the plant and the plant will nurture you!$$),
    ('35467', 11, $$That's how a girl from a village dreamed her birthday to be..@She feeded the poor and needy,@Cared for the nature, enjoyed her day with her friends and family. MEERA'S BEST BIRTHDAY EVER!!$$),
    ('35467', 12, $$The story didn't come to an end. That night two fairies Stella and flora visited Meera and gifted her a a piece of land.. Ever since than Meera believed even more strongly that,@"what we give is what we get"!$$),
    ('35476', 0, $$Once upon a time in a mountainous Musamba village there lived a famous blacksmith. The villagers called him Mungwala - the man of iron and steel.$$),
    ('35476', 1, $$Mungwala was known by everyone in the village. Villagers went to his hut every morning to watch him work. He seemed to be able to make anything with his iron and steel.$$),
    ('35476', 2, $$Sekwila, the village chief, heard about Mungwala's work. He sent his headmen to bring Mungwala to the palace.$$),
    ('35476', 3, $$Mungwala was happy to hear that Sekwila wanted to see him. "I will be very happy to work for the chief," he said.$$),
    ('35476', 4, $$So Mungwala went to the palace. "Mungwala, I have heard so much about your good work," said Sekwila. "I want you to do a very special task. "$$),
    ('35476', 5, $$"With your iron and steel, I want you to build a man who can walk, cry real tears and bleed real human blood. " "Impossible! " thought Mungwala. But no one could say no to the chief in this village.$$),
    ('35476', 6, $$Mungwala could not sleep that night. How was he going to do this impossible task? He was very scared and very worried.$$),
    ('35476', 7, $$Suddenly, Mungwala remembered a wise old man Kalaiti. Perhaps he could help. But where was Kalaiti? He had disappeared from the village. People said that it was because he had displeased the chief.$$),
    ('35476', 8, $$The next morning Mungwala did not go to work. He went up the mountains to think. While walking there, he saw a man sitting under a mupundu tree.$$),
    ('35476', 9, $$It was old Kalaiti! "I am so pleased to see you," said Mungwala. "I have a big problem. " He told Kalaiti the whole story. Kalaiti thought carefully, and then he said.$$),
    ('35476', 10, $$"Tell the chief that you will need a thousand 20 litres buckets full of tears and a thousand large clay pots full of hair. With the water, you will make blood. With the hair, you will make a fire to strengthen the steel man. " "Thank you, thank you! " Mungwala said, running back to the palace.$$),
    ('35476', 11, $$Mungwala said, "Sekwila, to do what you ask, I will need two things. A thousand 20 litres buckets full of tears; and a thousand large clay pots filled with hair from the heads of all the villagers. " Sekwila agreed. He asked his headmen to tell the villagers.$$),
    ('35476', 12, $$Cries were heard from every corner of the village. Young and old people cried day and night to fill a thousand buckets with tears. Every villager's head was shaved off and thrown into the pots. But the tears and hair of all the villagers were not enough to fill the buckets and pots.$$),
    ('35476', 13, $$Eventually Sekwila gave up and called Mungwala back to the palace. "Mungwala, you are a wise man, the wisest in the village," said Sekwila. "Will you do me the honour of being my chief headman? " Mungwala smiled.$$),
    ('35476', 14, $$"Only if you let Kalaiti come back to the village," he replied. So Mungwala became chief headman. And he and Kalaiti were the advisors of Sekwila.$$),
    ('35491', 0, $$Once upon a time in a Town far way, the people in that town have a habit of laughing at anyone that they think is not perfect in their eyes.$$),
    ('35491', 1, $$They laugh at the postman, because he walks with a lump. They laugh at Mr Bird, because he has one eye. They laugh at Chocolate, because she use her wheelchair to get around. They laugh at Vanilla, because he stammers when he talks.$$),
    ('35491', 2, $$One day, a stranger moved into the town. Each time the stranger would go out, he would wear a white mask to cover the left side of his face. The town people would laugh so hard each time they see him. Some would even go so far as throwing$$),
    ('35491', 3, $$stones at him. The stranger however was determine that no matter what the Town people did to him, he wasn't letting their ignorance drive him away.$$),
    ('35491', 4, $$A few months later, all the citizens of the Town, were ordered to attend a fire safety meeting at the Town Hall.$$),
    ('35491', 5, $$That morning before the meeting, the Town's people were informed by radio that there will be a special guest speaker at the fire safety meeting.$$),
    ('35491', 6, $$The people were excited and happy, they were all thinking that the special guest speaker must be someone very important.$$),
    ('35491', 7, $$Every seat at the Town Hall was filled that evening. The Mayor stood up and informed the Town people that the special guest speaker has something important to share with them. The Town people looked at each other and laughed.$$),
    ('35491', 8, $$Slowly, the stranger made his way to the front of the room. The stranger had removed the white mask that covered the burned disfigured left side of his face. The Town's people gasped, some turned away in shame, some held each others hand$$),
    ('35491', 9, $$as they fight away the tears rolling down their faces.$$),
    ('35491', 10, $$The stranger began, " My name is Aba Lopez and I am a retired fire fighter, two years ago, I was burned on my face in a house fire, while saving the life of a mother and her young child".$$),
    ('35491', 11, $$As the Town people listened and cried, they learned an important lesson that evening and promised never to laugh at anyone again. THE END$$),
    ('35553', 0, $$They was a nasty bug making lots of people poorly. For a long long time people could not fly or visit friends. When it was safe to fly Granny got on a big plane in Spain. Granny was so excited to be flying to visit Riley and Fia$$),
    ('35553', 1, $$Aunty KAZ, UNCLE Chris and Fia met Granny at the airport. They took Granny to Riley's house. Granny was super excited to see Riley and Fia. Granny had bought Riley and Fia lots of new clothes. She had also made them a dinasour egg each.$$),
    ('35553', 2, $$Granny had also come from Spain to paint Riley's new bedroom. Granny had made lots of pink, blue and purple butterfly stickers and mummy had got some pretty flowers stickers for Riley's wall. Riley and Fia helped Granny paint Riley's room.$$),
    ('35553', 3, $$Mummy, Granny, Fia and Riley went to the animal farm. When they were there they saw lots of animals. They saw goats, meerkats, horses, cows, rabbits, chicks, donkeys, alpacas and even a grumpy llama$$),
    ('35553', 4, $$At the farm Fia and Riley played at the park. Riley went up the big climbing frame with a big twisty slide, at first Riley was a little scared. So Granny went down the slide with Riley. Riley wasn't scared anymore, she was very brave.$$),
    ('35553', 5, $$Riley and Fia got to ride on a donkey. The donkeys were very gentle and they took Riley and Fia down to the bottom of the field and back to the start. It was fun to ride the donkeys.$$),
    ('35553', 6, $$Riley, Fia, Mummy and Granny all went on a tractor that took them all the way up a hill, where they saw lots of donkeys and they fed the donkeys some bread. The tractor ride was lots of fun, the donkeys were greedy and liked the bread.$$),
    ('35553', 7, $$After the tractor ride everyone went to the petting area. There Mummy held a fluffy brown rabbit so Riley and Fia could pet it. Mummy also held a chubby Guinea Pig and a baby chick. The baby chick was very small, yellow and super fluffy.$$),
    ('35553', 8, $$After lunch they visited the meerkats, the meerkats were very funny and played a lot. The meerkats liked to hide in their tunnels. After the meerkats they saw owls and other birds.$$),
    ('35553', 9, $$Before going home mummy, Riley, Fia and Granny had lunch then went back to the playpark. Riley and Fia played on the big toy train, Riley was the driver. Riley climbing frame and went down the big slide lots. They had lots and lots of fun$$),
    ('35554', 0, $$My name is SimNom$$),
    ('35554', 1, $$I have a friend called Gyeyok who comes from the village of Nok in Kaduna State Nigeria.$$),
    ('35554', 2, $$Gyeyok and I love to read our ABC$$),
    ('35554', 3, $$But our other friends prefer to play all-day.$$),
    ('35554', 4, $$Even though playing is good for the body, reading and playing help us to improve our reading skills while playing keeps us strong and healthy.$$),
    ('35574', 0, $$There was a girl called Batina. Her two friends were Katola and Mbane$$),
    ('35574', 1, $$One day, they went to the river to fetch water.$$),
    ('35574', 2, $$"Let's take our bath before going home", they told her.$$),
    ('35574', 3, $$Binta agreed. "Go in first, we will join you", they said.$$),
    ('35574', 4, $$They pushed her into the deep river and ran away.$$),
    ('35574', 5, $$Binta started screaming for help. A fisherman came and helped her.$$),
    ('35574', 6, $$Katala and Mbakana went home. They lied that Batina drowned in the river.$$),
    ('35574', 7, $$They were shocked to see Batina back. Batina forgave them. They promised not to be wicked again.$$),
    ('35582', 0, $$Once upon a time, there was a farmer named Tanko with his wife, named Fatima, in Zango village. @The family had two daughters, Marham and Amina and the parents sent them to Zango Primary School.$$),
    ('35582', 1, $$Maryam is the eldest daughter but always goes to school late, and sometimes she will not even go. She told her father that she was tired of going to school.@So the father asked Maryam what she wanted, and she choose to stay at home.$$),
    ('35582', 2, $$However, her younger sister, Amina, goes to school early turning to be the best students in her class.@For Maryam, all she likes doing is to play with the other children who do not go to school in the village.$$),
    ('35582', 3, $$In Primary six, Amina wrote the common Entrance Examination and scored the highest mark in her school and got a scholarship to go to Rumpa Secondary school.$$),
    ('35582', 4, $$Amina was eager to go to a new school where she met friends from diverse communities. @She started to lead her class in all examinations up to the final year when she sat for the Senior Secondary School and emerged as the best student.$$),
    ('35582', 5, $$Amina was offered a scholarship to study at Kangojo University. Amina studied hard and emerged as the best medical student of the year and got employed to work in one of the biggest hospitals in Kangojo city.$$),
    ('35582', 6, $$After the University, Amina married an Engineer and lives happily with her husband.@In a few years, Amina bought a house for her parents and they moved to ,Iive in Kangojo City, but her elder sister Maryam remained in the village.$$),
    ('35582', 7, $$It was at this point that Marham realized the importance of going to school and said that her children must go to school.$$),
    ('35588', 0, $$There lived a girl called Fatima who loved school,but she was not allow because her father does not believe in the education of a female child. One day, her mother was fed up with her father's attitude toward education.$$),
    ('35588', 1, $$'Baban Fatima what you are doing is not is right .that you did not go to school does not mean Fatima should not ',said Fatima's mother .$$),
    ('35588', 2, $$' keep quite,I am not going to enrol my daughter in school. 'Fatima's mother was not happy. After some time Fatima's mother requested the father to allow Fatima to live with her sister,Zainab, in the city.$$),
    ('35588', 3, $$Zainab enrolled Fatima in school. Fatima later became a nurse and worked in a hospital.$$),
    ('35588', 4, $$One day, Fatima's father, malam Tanko, took ill and was taken to the hospital where Fatima works suddenly, he saw that it was Fatima who was to him he was sorry and apologised to his daughter after realising he has made a great mistake.$$),
    ('35593', 0, $$Amina is a very beautiful girl. She is 13 years old.$$),
    ('35593', 1, $$Amina goes to Government Girls' Secondary School, Rafi.$$),
